// src/components/ROI/tabs/ProjectSavingsTab.js
import React, { useEffect, useMemo, useState } from "react";
import { useOutletContext } from "react-router-dom";

/**
 * Tab2 (Project Savings) from TabsUI.xlsx
 * Sections:
 *   - TDM Savings (Pre vs Post, with N,N1,N2,N3 and formulas)
 *   - Automation Savings:
 *       Test Prep, Execution DIT, Execution SIT, Execution UAT
 *       each with rows and formulas (0.25 coefficient in cost)
 *
 * Excel constants from Tab2:
 *  G37 = 27.85, G38 = 66.63  (rates used in cost calc)
 *  ROUNDUP(…,2) applied to PD calculations
 *  Savings = (C1 - C2) * N3   (except a special IF in UAT row for one cell)
 *
 * Also implements:
 *  - <Add Row> (red) for Automation sub-sections
 *  - <Dropdown1>, <Dropdown2>, <Dropdown3> (red) placeholders per row
 */
export default function ProjectSavingsTab() {
  const { intakeNumber } = useOutletContext();

  // === Rates from Excel ===
  const RATE_R1 = 27.85; // G37
  const RATE_R2 = 66.63; // G38

  // Helper ROUNDUP(x,2)
  const roundUp2 = (x) => Math.ceil((Number(x) || 0) * 100) / 100;

  // ---- TDM Savings ----
  const [tdm, setTdm] = useState({
    N: 0,        // Total deal count
    N1: 0,       // Manual Deal/day
    N2: 0,       // Avg Automation deal/day
    N3: 0,       // Number of cycles
    PD1: 0,      // = ROUNDUP(N / N1, 2)
    C1: 0,       // = PD1 * 8 * (R1 + 0.15*R2)
    PD2: 0,      // = ROUNDUP(N / N2, 2)
    C2: 0,       // = PD2 * 8 * (R1 + 0.15*R2)
    Savings: 0,  // = (C1 - C2) * N3
  });

  useEffect(() => {
    const PD1 = tdm.N1 ? roundUp2(tdm.N / tdm.N1) : 0;
    const C1 = PD1 * 8 * (RATE_R1 + 0.15 * RATE_R2);
    const PD2 = tdm.N2 ? roundUp2(tdm.N / tdm.N2) : 0;
    const C2 = PD2 * 8 * (RATE_R1 + 0.15 * RATE_R2);
    const S = (C1 - C2) * (Number(tdm.N3) || 0);
    setTdm((p) => ({ ...p, PD1, C1, PD2, C2, Savings: S }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tdm.N, tdm.N1, tdm.N2, tdm.N3]);

  // ---- Automation Savings (four subsections, rows with dropdowns) ----
  const mkAutoRow = () => ({
    Dropdown1: "",
    Dropdown2: "",
    Dropdown3: "",
    N: 100, // “100” cells in Excel are user-entered defaults
    N1: 100,
    N2: 100,
    N3: 100,
    PD1: 0,
    C1: 0,
    PD2: 0,
    C2: 0,
    Savings: 0,
  });

  const [prepRows, setPrepRows] = useState([mkAutoRow()]);
  const [ditRows, setDitRows] = useState([mkAutoRow()]);
  const [sitRows, setSitRows] = useState([mkAutoRow()]);
  const [uatRows, setUatRows] = useState([mkAutoRow()]);

  const DROPDOWN_OPTIONS_1 = []; // TODO: fetch from DB later
  const DROPDOWN_OPTIONS_2 = [];
  const DROPDOWN_OPTIONS_3 = [];

  const recomputeAuto = (rows, coeff) =>
    rows.map((r) => {
      const PD1 = r.N1 ? roundUp2(r.N / r.N1) : 0;
      const C1 = PD1 * 8 * (RATE_R1 + coeff * RATE_R2);
      const PD2 = r.N2 ? Number(r.N) / Number(r.N2) : 0; // Excel uses =E/J (no roundup here in sheet snippets)
      const C2 = PD2 * 8 * (RATE_R1 + coeff * RATE_R2);
      // Default Savings = (C1 - C2) * N3
      let S = (C1 - C2) * (Number(r.N3) || 0);
      return { ...r, PD1, C1, PD2, C2, Savings: S };
    });

  // Test Prep / DIT / SIT subsections: coefficient = 0.25
  useEffect(() => {
    setPrepRows((rows) => recomputeAuto(rows, 0.25));
  }, [prepRows.length]);
  useEffect(() => {
    setDitRows((rows) => recomputeAuto(rows, 0.25));
  }, [ditRows.length]);
  useEffect(() => {
    setSitRows((rows) => recomputeAuto(rows, 0.25));
  }, [sitRows.length]);

  // UAT: also 0.25, but one cell in Excel shows IF(E29=0,0,I29-L29). We handle E=0 edge:
  const recomputeUAT = (rows) =>
    rows.map((r) => {
      const PD1 = r.N1 ? roundUp2(r.N / r.N1) : 0;
      const C1 = PD1 * 8 * (RATE_R1 + 0.25 * RATE_R2);
      const PD2 = r.N2 ? Number(r.N) / Number(r.N2) : 0;
      const C2 = PD2 * 8 * (RATE_R1 + 0.25 * RATE_R2);
      let base = C1 - C2;
      if (!r.N) base = 0; // IF(E=0,0, I-L)
      const S = base * (Number(r.N3) || 0);
      return { ...r, PD1, C1, PD2, C2, Savings: S };
    });
  useEffect(() => {
    setUatRows((rows) => recomputeUAT(rows));
  }, [uatRows.length]);

  // When values change inside any row, recompute immediately
  const updateRow = (rows, setRows, idx, key, val, coeff = 0.25, isUAT = false) => {
    const copy = [...rows];
    copy[idx] = { ...copy[idx], [key]: val };
    setRows(isUAT ? recomputeUAT(copy) : recomputeAuto(copy, coeff));
  };

  const addRow = (setRows) => setRows((prev) => [...prev, mkAutoRow()]);

  // Totals for Automation Savings header cell (=N14+N19+N24+N29 in Excel)
  const autoSavingsTotal = useMemo(() => {
    const sumSection = (arr) => arr.reduce((s, r) => s + (Number(r.Savings) || 0), 0);
    return sumSection(prepRows) + sumSection(ditRows) + sumSection(sitRows) + sumSection(uatRows);
  }, [prepRows, ditRows, sitRows, uatRows]);

  return (
    <div className="tab-wrap">
      {/* ===== TDM Savings ===== */}
      <div className="tab-section tab-section-yellow">TDM Savings</div>
      <div className="grid-2">
        <label className="tab-label tab-label-green">Total deal count (N)</label>
        <input className="tab-input" type="number" value={tdm.N} onChange={(e) => setTdm({ ...tdm, N: Number(e.target.value) })} />
        <label className="tab-label tab-label-green">Manual Deal creation per day (N1)</label>
        <input className="tab-input" type="number" value={tdm.N1} onChange={(e) => setTdm({ ...tdm, N1: Number(e.target.value) })} />
        <label className="tab-label tab-label-orange">Total PD (PD1 = ROUNDUP(N/N1,2))</label>
        <input className="tab-input tab-input-orange" value={tdm.PD1} disabled />
        <label className="tab-label tab-label-orange">Cost (C1 = PD1*8*(R1+0.15*R2))</label>
        <input className="tab-input tab-input-orange" value={tdm.C1} disabled />
        <label className="tab-label tab-label-green">Average Automation deal creation per day (N2)</label>
        <input className="tab-input" type="number" value={tdm.N2} onChange={(e) => setTdm({ ...tdm, N2: Number(e.target.value) })} />
        <label className="tab-label tab-label-orange">Total PD (PD2 = ROUNDUP(N/N2,2))</label>
        <input className="tab-input tab-input-orange" value={tdm.PD2} disabled />
        <label className="tab-label tab-label-orange">Cost (C2 = PD2*8*(R1+0.15*R2))</label>
        <input className="tab-input tab-input-orange" value={tdm.C2} disabled />
        <label className="tab-label tab-label-green">Number of cycles (N3)</label>
        <input className="tab-input" type="number" value={tdm.N3} onChange={(e) => setTdm({ ...tdm, N3: Number(e.target.value) })} />
        <label className="tab-label tab-label-orange">Savings = (C1 - C2) * N3</label>
        <input className="tab-input tab-input-orange" value={tdm.Savings} disabled />
      </div>

      {/* Header total (orange cell like H8 in the sheet) */}
      <div className="grid-2 mt-2">
        <label className="tab-label tab-label-orange">Automation Savings Total</label>
        <input className="tab-input tab-input-orange" value={autoSavingsTotal} disabled />
      </div>

      {/* ===== Automation Savings ===== */}
      <div className="tab-section tab-section-yellow">Automation Savings</div>

      {/* --- Section: Test Prep --- */}
      <div className="tab-subsection">
        <div className="tab-subtitle">Test Prep</div>
        <div className="tab-row-actions">
          {/* Buttons and dropdowns in red */}
          <button className="btn-red" onClick={() => addRow(setPrepRows)}>
            &lt;Add Row&gt;
          </button>
          <select className="select-red">
            <option value="">{`<Dropdown1>`}</option>
            {DROPDOWN_OPTIONS_1.map((o) => (
              <option key={o} value={o}>{o}</option>
            ))}
          </select>
          <select className="select-red">
            <option value="">{`<Dropdown2>`}</option>
            {DROPDOWN_OPTIONS_2.map((o) => (
              <option key={o} value={o}>{o}</option>
            ))}
          </select>
          <select className="select-red">
            <option value="">{`<Dropdown3>`}</option>
            {DROPDOWN_OPTIONS_3.map((o) => (
              <option key={o} value={o}>{o}</option>
            ))}
          </select>
        </div>

        {prepRows.map((r, i) => (
          <div key={`prep-${i}`} className="grid-8">
            <input className="tab-input" type="number" value={r.N} onChange={(e) => updateRow(prepRows, setPrepRows, i, "N", Number(e.target.value))} placeholder="N (Total count)" />
            <input className="tab-input" type="number" value={r.N1} onChange={(e) => updateRow(prepRows, setPrepRows, i, "N1", Number(e.target.value))} placeholder="N1 (Manual/day)" />
            <input className="tab-input tab-input-orange" value={r.PD1} disabled placeholder="PD1" />
            <input className="tab-input tab-input-orange" value={r.C1} disabled placeholder="C1" />
            <input className="tab-input" type="number" value={r.N2} onChange={(e) => updateRow(prepRows, setPrepRows, i, "N2", Number(e.target.value))} placeholder="N2 (Auto/day)" />
            <input className="tab-input tab-input-orange" value={r.PD2} disabled placeholder="PD2" />
            <input className="tab-input tab-input-orange" value={r.C2} disabled placeholder="C2" />
            <input className="tab-input" type="number" value={r.N3} onChange={(e) => updateRow(prepRows, setPrepRows, i, "N3", Number(e.target.value))} placeholder="N3 (cycles)" />
            <input className="tab-input tab-input-orange" value={r.Savings} disabled placeholder="Savings" />
          </div>
        ))}
      </div>

      {/* --- Section: Execution DIT --- */}
      <div className="tab-subsection">
        <div className="tab-subtitle">Execution DIT</div>
        <div className="tab-row-actions">
          <button className="btn-red" onClick={() => addRow(setDitRows)}>&lt;Add Row&gt;</button>
          <select className="select-red"><option value="">{`<Dropdown1>`}</option></select>
          <select className="select-red"><option value="">{`<Dropdown2>`}</option></select>
          <select className="select-red"><option value="">{`<Dropdown3>`}</option></select>
        </div>
        {ditRows.map((r, i) => (
          <div key={`dit-${i}`} className="grid-8">
            <input className="tab-input" type="number" value={r.N} onChange={(e) => updateRow(ditRows, setDitRows, i, "N", Number(e.target.value))} placeholder="N" />
            <input className="tab-input" type="number" value={r.N1} onChange={(e) => updateRow(ditRows, setDitRows, i, "N1", Number(e.target.value))} placeholder="N1" />
            <input className="tab-input tab-input-orange" value={r.PD1} disabled />
            <input className="tab-input tab-input-orange" value={r.C1} disabled />
            <input className="tab-input" type="number" value={r.N2} onChange={(e) => updateRow(ditRows, setDitRows, i, "N2", Number(e.target.value))} placeholder="N2" />
            <input className="tab-input tab-input-orange" value={r.PD2} disabled />
            <input className="tab-input tab-input-orange" value={r.C2} disabled />
            <input className="tab-input" type="number" value={r.N3} onChange={(e) => updateRow(ditRows, setDitRows, i, "N3", Number(e.target.value))} placeholder="N3" />
            <input className="tab-input tab-input-orange" value={r.Savings} disabled />
          </div>
        ))}
      </div>

      {/* --- Section: Execution SIT --- */}
      <div className="tab-subsection">
        <div className="tab-subtitle">Execution SIT</div>
        <div className="tab-row-actions">
          <button className="btn-red" onClick={() => addRow(setSitRows)}>&lt;Add Row&gt;</button>
          <select className="select-red"><option value="">{`<Dropdown1>`}</option></select>
          <select className="select-red"><option value="">{`<Dropdown2>`}</option></select>
          <select className="select-red"><option value="">{`<Dropdown3>`}</option></select>
        </div>
        {sitRows.map((r, i) => (
          <div key={`sit-${i}`} className="grid-8">
            <input className="tab-input" type="number" value={r.N} onChange={(e) => updateRow(sitRows, setSitRows, i, "N", Number(e.target.value))} placeholder="N" />
            <input className="tab-input" type="number" value={r.N1} onChange={(e) => updateRow(sitRows, setSitRows, i, "N1", Number(e.target.value))} placeholder="N1" />
            <input className="tab-input tab-input-orange" value={r.PD1} disabled />
            <input className="tab-input tab-input-orange" value={r.C1} disabled />
            <input className="tab-input" type="number" value={r.N2} onChange={(e) => updateRow(sitRows, setSitRows, i, "N2", Number(e.target.value))} placeholder="N2" />
            <input className="tab-input tab-input-orange" value={r.PD2} disabled />
            <input className="tab-input tab-input-orange" value={r.C2} disabled />
            <input className="tab-input" type="number" value={r.N3} onChange={(e) => updateRow(sitRows, setSitRows, i, "N3", Number(e.target.value))} placeholder="N3" />
            <input className="tab-input tab-input-orange" value={r.Savings} disabled />
          </div>
        ))}
      </div>

      {/* --- Section: Execution UAT --- */}
      <div className="tab-subsection">
        <div className="tab-subtitle">Execution UAT</div>
        <div className="tab-row-actions">
          <button className="btn-red" onClick={() => addRow(setUatRows)}>&lt;Add Row&gt;</button>
          <select className="select-red"><option value="">{`<Dropdown1>`}</option></select>
          <select className="select-red"><option value="">{`<Dropdown2>`}</option></select>
          <select className="select-red"><option value="">{`<Dropdown3>`}</option></select>
        </div>
        {uatRows.map((r, i) => (
          <div key={`uat-${i}`} className="grid-8">
            <input className="tab-input" type="number" value={r.N} onChange={(e) => updateRow(uatRows, setUatRows, i, "N", Number(e.target.value), 0.25, true)} placeholder="N" />
            <input className="tab-input" type="number" value={r.N1} onChange={(e) => updateRow(uatRows, setUatRows, i, "N1", Number(e.target.value), 0.25, true)} placeholder="N1" />
            <input className="tab-input tab-input-orange" value={r.PD1} disabled />
            <input className="tab-input tab-input-orange" value={r.C1} disabled />
            <input className="tab-input" type="number" value={r.N2} onChange={(e) => updateRow(uatRows, setUatRows, i, "N2", Number(e.target.value), 0.25, true)} placeholder="N2" />
            <input className="tab-input tab-input-orange" value={r.PD2} disabled />
            <input className="tab-input tab-input-orange" value={r.C2} disabled />
            <input className="tab-input" type="number" value={r.N3} onChange={(e) => updateRow(uatRows, setUatRows, i, "N3", Number(e.target.value), 0.25, true)} placeholder="N3" />
            <input className="tab-input tab-input-orange" value={r.Savings} disabled />
          </div>
        ))}
      </div>
    </div>
  );
}
